<?php
require_once __DIR__ . '/_friend_helpers.php';
try { if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $d=friends_input(); $c=friends_connection(); if(!SessionHelper::isAuthenticated()){ApiResponse::unauthorized();exit;} if(!friends_require_active($c)){ApiResponse::forbidden('Active account required.');exit;} if(!friends_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} $sender=SessionHelper::getUserId(); $target=(int)($d['user_id']??0); if($target<=0||!friends_active($c,$target)){ApiResponse::notFound('User not found.');exit;} if($target===$sender){ApiResponse::validation(['user_id'=>'You cannot add yourself.']);exit;} if(friends_are_blocked($c,$sender,$target)){ApiResponse::forbidden('Friend request blocked.');exit;} if(friends_are_friends($c,$sender,$target)){ApiResponse::send(false,[],'Already friends.',[],409);exit;} $pending=friends_pending($c,$sender,$target); if($pending){ApiResponse::send(false,['status'=>friends_status($c,$sender,$target)],'Request already pending.',[],409);exit;} $s=$c->prepare("INSERT INTO friend_requests (sender_id,receiver_id,status) VALUES (:s,:r,'pending')");$s->execute(['s'=>$sender,'r'=>$target]); ApiResponse::success(['request_id'=>(int)$c->lastInsertId()],'Friend request sent.',201); } catch(Throwable $e){Logger::error('Friend send failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to send request.');}
?>
